extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var equip_script: Script = load("res://equipment_item.gd")
	if not check("equip_script", equip_script != null, "equipment_item.gd deve esistere e compilare"):
		return
	var helmet: Variant = equip_script.new("Elmo di Ferro", 120, 15)
	if not check("istanza_elmo", helmet != null, "EquipmentItem deve potersi creare con _init(nome, prezzo, difesa)"):
		return
	check("is_item", helmet is Item, "EquipmentItem deve estendere Item ed essere riconosciuto con 'is Item'")
	var desc: String = call_if_exists(helmet, "get_description", [], "")
	check("descrizione", desc.contains("Elmo di Ferro") and desc.contains("120") and desc.contains("15"), "get_description() deve includere nome, prezzo e difesa: '%s'" % desc)

	var inv := Inventory.new()
	check("metodo_count_equipment", has_function(inv, "count_equipment"), "Inventory deve avere la funzione count_equipment()")
	inv.add_item(Item.new("Gemma grezza", 50))
	inv.add_item(ConsumableItem.new("Pozione", 20, 30))
	inv.add_item(helmet)
	inv.add_item(equip_script.new("Scudo di Legno", 60, 8))

	var total_val: int = inv.calculate_total_value()
	check("totale_valore", total_val == 250, "calculate_total_value() deve continuare a funzionare (atteso 250, ottenuto %d)" % total_val)
	var count_cons: int = inv.count_consumables()
	check("totale_consumabili", count_cons == 1, "count_consumables() deve restituire 1 (ottenuto %d)" % count_cons)
	var count_eq: int = call_if_exists(inv, "count_equipment", [], 0)
	check("totale_equip", count_eq == 2, "count_equipment() deve restituire 2 (ottenuto %d)" % count_eq)

