class_name Inventory
extends RefCounted

var items: Array[Item] = []


func add_item(item: Item) -> void:
	if item != null:
		items.append(item)


func calculate_total_value() -> int:
	var total: int = 0
	for item in items:
		total += item.price
	return total


func count_consumables() -> int:
	var count: int = 0
	for item in items:
		if item is ConsumableItem:
			count += 1
	return count

